(function(E){ const x = E["exam-01"] = E["exam-01"] || {units:{}}; (x.units = x.units || {})["x01-r3"] = {"id":"x01-r3","patterns":["RA-history","GT3-life","PARA-research"],"title":{"en":"Reading 3: Passage 3 / Section 3","tr":"Reading 3: Passage 3 / Section 3","fa":"Reading ۳: متن ۳ (Passage 3) / بخش ۳ (Section 3)"},"objective":{"en":"In this lesson you will learn to follow a writer’s opinion through a review: answer multiple choice questions, complete a summary from a box of words, and decide YES, NO or NOT GIVEN about the writer’s views.","tr":"Bu derste bir eleştiri boyunca yazarın görüşünü takip etmeyi öğreneceksin: çoktan seçmeli soruları cevaplayacak, bir özeti kelime kutusundan tamamlayacak ve yazarın görüşleri için YES, NO ya da NOT GIVEN’a karar vereceksin.","fa":"در این درس یاد می‌گیری نظر نویسنده را در یک نقد دنبال کنی: به سؤال‌های چندگزینه‌ای جواب بدهی، یک خلاصه را از کادر کلمه‌ها کامل کنی و درباره‌ی نظرهای نویسنده بین YES، NO و NOT GIVEN تصمیم بگیری."},"objectiveGT":{"en":"In this lesson you will learn to read a longer general article: complete notes with up to three words from the text, and decide TRUE, FALSE or NOT GIVEN when the text is careful about what is proved.","tr":"Bu derste daha uzun, genel bir makaleyi okumayı öğreneceksin: notları metinden en fazla üç kelimeyle tamamlayacak ve metin neyin kanıtlandığı konusunda temkinli olduğunda TRUE, FALSE ya da NOT GIVEN’a karar vereceksin.","fa":"در این درس یاد می‌گیری یک مقاله‌ی عمومیِ بلندتر را بخوانی: یادداشت‌ها را با حداکثر سه کلمه از متن کامل کنی و وقتی متن درباره‌ی چیزهای ثابت‌شده محتاط است، بین TRUE، FALSE و NOT GIVEN تصمیم بگیری."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 3: a book review","tr":"Reading Passage 3: bir kitap eleştirisi","fa":"Reading Passage 3: نقد یک کتاب"},"objective":{"en":"In this lesson you will learn to follow a writer’s opinion through a review: answer multiple choice questions, complete a summary from a box of words, and decide YES, NO or NOT GIVEN about the writer’s views.","tr":"Bu derste bir eleştiri boyunca yazarın görüşünü takip etmeyi öğreneceksin: çoktan seçmeli soruları cevaplayacak, bir özeti kelime kutusundan tamamlayacak ve yazarın görüşleri için YES, NO ya da NOT GIVEN’a karar vereceksin.","fa":"در این درس یاد می‌گیری نظر نویسنده را در یک نقد دنبال کنی: به سؤال‌های چندگزینه‌ای جواب بدهی، یک خلاصه را از کادر کلمه‌ها کامل کنی و درباره‌ی نظرهای نویسنده بین YES، NO و NOT GIVEN تصمیم بگیری."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"14"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}},{"label":{"en":"Words in the box","tr":"Kutudaki kelime","fa":"کلمه‌های کادر"},"value":"9"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a history of salt","tr":"Bu sınav: tuzun tarihi","fa":"این آزمون: تاریخ نمک"},"intro":{"en":"Passage 3 is the hardest text: often a review, an argument or a debate between experts. The writer has a view, and the questions test whether you can separate it from the facts and from other people’s views.","tr":"Passage 3 en zor metindir: çoğu zaman bir eleştiri, bir tartışma ya da uzmanlar arasında bir münazara. Yazarın bir görüşü vardır ve sorular onu gerçeklerden ve başkalarının görüşlerinden ayırıp ayıramadığını ölçer.","fa":"Passage 3 سخت‌ترین متن است: اغلب یک نقد، یک استدلال یا بحثی بین متخصص‌ها. نویسنده نظری دارد و سؤال‌ها می‌سنجند که می‌توانی آن را از واقعیت‌ها و از نظر دیگران جدا کنی یا نه."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x01-r3-ctx","exam":true,"patterns":["RA-history","PARA-research"],"often":{"pattern":"RA-history","n":35,"of":120,"label":{"en":"Comes up often in the real exam: 35 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 35’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۵ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"A review of a history book","tr":"Bir tarih kitabının eleştirisi","fa":"نقد یک کتاب تاریخی"},"asks":{"en":"A reviewer describes what a book covers, praises some parts and criticises others. Passage 3 is often a review or an argument, so the questions ask what the writer thinks, not only what the text says.","tr":"Bir eleştirmen bir kitabın neyi anlattığını açıklıyor, bazı kısımlarını övüyor, bazılarını eleştiriyor. Passage 3 çoğu zaman bir eleştiri ya da tartışmadır; bu yüzden sorular yalnızca metnin ne dediğini değil, yazarın ne düşündüğünü de sorar.","fa":"یک منتقد توضیح می‌دهد کتاب درباره‌ی چیست، بخش‌هایی را تحسین و بخش‌هایی را نقد می‌کند. Passage 3 اغلب نقد یا استدلال است، پس سؤال‌ها می‌پرسند نویسنده چه فکر می‌کند، نه فقط اینکه متن چه می‌گوید."},"fields":["What the book covers","Strengths","Weaknesses","The reviewer’s overall view","What other people think"],"words":[{"a":"lively style","b":"energetic / a pleasure to read","tr":"canlı üslup","fa":"سبک پرانرژی"},{"a":"criticism","b":"weakness / reservations / a pity","tr":"eleştiri","fa":"انتقاد"},{"a":"praise","b":"at its best / rewarding / impressive","tr":"övgü","fa":"تحسین"},{"a":"no clear argument","b":"lacks a central idea / no clear thesis","tr":"net bir savı yok","fa":"استدلال روشنی ندارد"},{"a":"missed opportunity","b":"it could have been much more","tr":"kaçırılmış fırsat","fa":"فرصت ازدست‌رفته"},{"a":"led to","b":"resulted in / drove people to","tr":"yeni teknolojiye yol açtı","fa":"به فناوری تازه منجر شد"},{"a":"made real","b":"brought to life","tr":"gerçek hissettirdi","fa":"ملموس کرد"},{"a":"rare","b":"scarce","tr":"nadir, kıt","fa":"کمیاب"},{"a":"found","b":"revealed","tr":"ortaya çıkardı","fa":"آشکار کرد"},{"a":"some reviewers think","b":"other critics have praised / some readers feel","tr":"bazı eleştirmenler düşünüyor","fa":"بعضی منتقدان فکر می‌کنند"},{"a":"in my view","b":"to me / I found that","tr":"bence","fa":"به نظر من"},{"a":"not suitable for","b":"is not the right book for","tr":"... için uygun değil","fa":"مناسبِ ... نیست"}],"traps":[{"en":"Whose voice? \"Other critics have praised the ending\" is not the writer’s view. Look for the writer’s own words: I, to me, in my view, I found.","tr":"Kimin sesi? \"Başka eleştirmenler sonu övdü\" yazarın görüşü değil. Yazarın kendi sözlerini ara: I, to me, in my view, I found.","fa":"صدای چه کسی؟ «منتقدان دیگر پایان را تحسین کرده‌اند» نظر نویسنده نیست. دنبال حرف خودِ نویسنده بگرد: I، to me، in my view، I found."},{"en":"Summary box: some words in the box also appear in the text but fit no gap. Check the grammar and the meaning of the whole sentence.","tr":"Özet kutusu: kutudaki bazı kelimeler metinde de geçer ama hiçbir boşluğa uymaz. Cümlenin tamamının dilbilgisini ve anlamını kontrol et.","fa":"کادر خلاصه: بعضی کلمه‌های کادر در متن هم آمده‌اند اما در هیچ جای خالی جا نمی‌شوند. دستور و معنیِ کل جمله را چک کن."},{"en":"A mixed opinion is not a NO: \"it is long, but rarely dull\" means the writer is mainly positive.","tr":"Karışık bir görüş NO değildir: \"uzun ama nadiren sıkıcı\" yazarın çoğunlukla olumlu olduğunu gösterir.","fa":"نظر دوگانه NO نیست: «طولانی است، اما به‌ندرت خسته‌کننده» یعنی نویسنده بیشتر نظر مثبت دارد."}],"example":{"text":"\"Some critics found the ending sentimental. I thought it was the most honest part of the novel.\"","item":"Statement: The ending of the novel is too sentimental. YES, NO or NOT GIVEN?","answer":"NO","why":{"en":"\"Some critics\" is another voice. The writer thinks the ending is honest, so the statement contradicts the writer’s view.","tr":"\"Bazı eleştirmenler\" başka bir ses. Yazar sonun dürüst olduğunu düşünüyor; yani ifade yazarın görüşüyle çelişiyor.","fa":"«بعضی منتقدان» صدای دیگری است. نویسنده پایان را صادقانه می‌داند، پس جمله با نظر او تناقض دارد."}}},{"id":"RA-culture","ctx":["RA-history","RA-culture"],"title":{"en":"Arguments about art, heritage and history","tr":"Sanat, miras ve tarih üzerine tartışma yazıları","fa":"نوشته‌های استدلالی درباره‌ی هنر، میراث و تاریخ"},"asks":{"en":"A review or an argument about art, museums, heritage or history: should museums return objects, is street art real art, what a history book gets right. YES/NO/NOT GIVEN asks about the writer’s views; multiple choice asks about the writer’s purpose.","tr":"Sanat, müzeler, kültürel miras ya da tarih üzerine bir eleştiri veya tartışma yazısı: müzeler eserleri iade etmeli mi, sokak sanatı gerçek sanat mı, bir tarih kitabı neyi doğru yapıyor. YES/NO/NOT GIVEN yazarın görüşlerini sorar; çoktan seçmeli sorular yazarın amacını sorar.","fa":"نقد یا نوشته‌ای استدلالی درباره‌ی هنر، موزه‌ها، میراث یا تاریخ: آیا موزه‌ها باید اشیا را پس بدهند، آیا هنر خیابانی هنر واقعی است، یک کتاب تاریخ چه چیزی را درست می‌گوید. YES/NO/NOT GIVEN نظر نویسنده را می‌پرسد؛ چندگزینه‌ای هدف نویسنده را."},"fields":["The writer believes the book is too long. (YES / NO / NOT GIVEN)","The writer’s main point in paragraph 3 is...","Museums should charge for entry. (YES / NO / NOT GIVEN)","Summary with a box: the writer thinks the ___ of the exhibition was..."],"words":[{"a":"the writer believes","b":"in my view / I would argue","tr":"yazara göre","fa":"نویسنده معتقد است"},{"a":"convincing","b":"persuasive / makes a strong case","tr":"ikna edici","fa":"قانع‌کننده"},{"a":"overrated","b":"praised more than it deserves","tr":"abartılmış","fa":"بیش از اندازه ستوده‌شده"},{"a":"neglected","b":"ignored / overlooked","tr":"ihmal edilmiş","fa":"نادیده‌گرفته‌شده"},{"a":"authentic","b":"genuine / the real thing","tr":"özgün","fa":"اصیل"},{"a":"controversial","b":"causes disagreement","tr":"tartışmalı","fa":"بحث‌برانگیز"},{"a":"heritage","b":"the past a community keeps","tr":"kültürel miras","fa":"میراث"},{"a":"accessible","b":"easy for the public to reach or understand","tr":"erişilebilir","fa":"در دسترس"},{"a":"criticise","b":"find fault with","tr":"eleştirmek","fa":"انتقاد کردن"},{"a":"underestimate","b":"think it matters less than it does","tr":"küçümsemek","fa":"دست‌کم گرفتن"},{"a":"admittedly","b":"it is true that... but","tr":"kabul etmek gerekir ki","fa":"البته"},{"a":"dismiss","b":"reject without serious thought","tr":"önemsememek","fa":"رد کردن"}],"traps":[{"en":"Reported views: \"some critics say the exhibition is too small\" is not the writer’s view unless the writer agrees.","tr":"Aktarılan görüşler: \"bazı eleştirmenler serginin küçük olduğunu söylüyor\" yazar katılmadıkça yazarın görüşü değildir.","fa":"نظرهای نقل‌شده: «بعضی منتقدها می‌گویند نمایشگاه کوچک است» نظر نویسنده نیست، مگر اینکه نویسنده موافق باشد."},{"en":"NOT GIVEN: the writer discusses the topic but gives no opinion on the exact point of the statement.","tr":"NOT GIVEN: yazar konuyu tartışır ama ifadedeki noktaya dair görüş bildirmez.","fa":"NOT GIVEN: نویسنده درباره‌ی موضوع حرف می‌زند، ولی درباره‌ی همان نکته‌ی جمله نظری نمی‌دهد."},{"en":"Concession: \"it is true that the museum is expensive, but...\". The writer’s real view comes after \"but\".","tr":"Kabul etme: \"müzenin pahalı olduğu doğru ama...\". Yazarın asıl görüşü \"but\"tan sonra gelir.","fa":"پذیرش موقت: «درست است که موزه گران است، اما...». نظر واقعی نویسنده بعد از «but» می‌آید."}],"example":{"text":"Critics have called the new gallery cold and unwelcoming. I disagree: its plain white rooms let the paintings speak for themselves, which is exactly what a gallery should do.","item":"Statement: The writer thinks the new gallery is unwelcoming.  (YES / NO / NOT GIVEN)","answer":"NO","why":{"en":"\"Unwelcoming\" is the critics’ view. \"I disagree\" makes the writer’s view the opposite: NO.","tr":"\"Soğuk\" eleştirmenlerin görüşü. \"Katılmıyorum\" yazarın görüşünü tersine çeviriyor: NO.","fa":"«بی‌روح» نظر منتقدهاست. «موافق نیستم» نظر نویسنده را برعکس می‌کند: NO."}},"track":"academic","general":true,"patterns":["RA-history"],"often":{"pattern":"RA-history","n":35,"of":120,"label":{"en":"Comes up often in the real exam: 35 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 35’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۵ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Four choices, a box, four views","tr":"Dört seçim, bir kutu, dört görüş","fa":"چهار سؤال، یک کادر، چهار نظر"},"body":{"en":"Questions 27-30: choose A, B, C or D. Questions 31-36: complete the summary with words from a box, A-I; three words are not used. Questions 37-40: YES, NO or NOT GIVEN, about the views of the writer.","tr":"Soru 27-30: A, B, C ya da D’yi seç. Soru 31-36: özeti A-I arasındaki bir kutudaki kelimelerle tamamla; üç kelime kullanılmaz. Soru 37-40: yazarın görüşleri hakkında YES, NO ya da NOT GIVEN.","fa":"سؤال‌های ۲۷ تا ۳۰: A، B، C یا D را انتخاب کن. سؤال‌های ۳۱ تا ۳۶: خلاصه را با کلمه‌های یک کادر (A تا I) کامل کن؛ سه کلمه استفاده نمی‌شوند. سؤال‌های ۳۷ تا ۴۰: YES، NO یا NOT GIVEN درباره‌ی نظرهای نویسنده."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Read the first and last paragraphs first: they usually hold the writer’s overall view.","tr":"Önce ilk ve son paragrafları oku: genelde yazarın genel görüşü oradadır.","fa":"اول پاراگراف اول و آخر را بخوان: معمولاً نظر کلی نویسنده آن‌جاست."},{"en":"Multiple choice: find the place, then reject each wrong option for a reason.","tr":"Çoktan seçmeli: yeri bul, sonra her yanlış seçeneği bir nedenle ele.","fa":"چندگزینه‌ای: جایش را پیدا کن، بعد هر گزینه‌ی غلط را با یک دلیل رد کن."},{"en":"Summary box: decide the word class for each gap, then choose by meaning; the box words are often paraphrases.","tr":"Özet kutusu: her boşluk için kelime türüne karar ver, sonra anlama göre seç; kutudaki kelimeler çoğu zaman eş anlamlıdır.","fa":"کادر خلاصه: نوع کلمه‌ی هر جای خالی را تعیین کن، بعد بر اساس معنی انتخاب کن؛ کلمه‌های کادر اغلب معادل‌اند."},{"en":"YES / NO / NOT GIVEN: mark who is speaking (the writer or others) before you answer.","tr":"YES / NO / NOT GIVEN: cevaplamadan önce kimin konuştuğunu işaretle (yazar mı, başkaları mı).","fa":"YES / NO / NOT GIVEN: قبل از جواب دادن علامت بزن چه کسی حرف می‌زند (نویسنده یا دیگران)."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"The writer’s view, not the facts","tr":"Gerçekler değil, yazarın görüşü","fa":"نظر نویسنده، نه واقعیت‌ها"},"table":{"headers":{"en":["The writer...","The answer"],"tr":["Yazar...","Cevap"],"fa":["نویسنده...","جواب"]},"rows":[["agrees with the statement","YES"],["says the opposite","NO"],["gives no opinion on it, or only reports what others think","NOT GIVEN"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One view, step by step","tr":"Bir görüş, adım adım","fa":"یک نظر، قدم به قدم"},"instruction":"Do the following statements agree with the views of the writer?","text":"\"Many readers have called the biography too long. I found every chapter worth reading.\"","item":"Statement: The biography is too long.","answer":"NO","walk":[{"en":"\"Many readers\" is another voice. Do not stop there.","tr":"\"Many readers\" başka bir ses. Orada durma.","fa":"«Many readers» صدای دیگری است. آن‌جا نایست."},{"en":"The writer’s voice: \"I found every chapter worth reading.\"","tr":"Yazarın sesi: \"Her bölümü okumaya değer buldum.\"","fa":"صدای نویسنده: «به نظرم همه‌ی فصل‌ها ارزش خواندن داشتند»."},{"en":"The writer disagrees with \"too long\": NO.","tr":"Yazar \"çok uzun\" görüşüne katılmıyor: NO.","fa":"نویسنده با «خیلی طولانی» مخالف است: NO."}]},"quick":{"prompt":"Text: \"The author clearly knows his subject, although the book is badly organised.\" Statement: \"The author is an expert on the subject.\" YES, NO or NOT GIVEN?","options":["NO","YES","NOT GIVEN"],"correct":1,"why":{"en":"\"Clearly knows his subject\" = the writer thinks he is an expert. The criticism is about organisation, not knowledge.","tr":"\"Konusunu açıkça biliyor\" = yazar onun uzman olduğunu düşünüyor. Eleştiri bilgiyle değil, düzenle ilgili.","fa":"«آشکارا موضوعش را می‌شناسد» یعنی نویسنده او را متخصص می‌داند. انتقاد درباره‌ی نظم کتاب است، نه دانش."}},"remember":{"en":"Find the writer’s own voice: I, to me, in my view. Other people’s views are not the answer.","tr":"Yazarın kendi sesini bul: I, to me, in my view. Başkalarının görüşleri cevap değildir.","fa":"صدای خودِ نویسنده را پیدا کن: I، to me، in my view. نظر دیگران جواب نیست."},"type":"explain","id":"c-x01-r3-e","course":"ielts-exams","exam":"exam-01","unit":"x01-r3"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 3","title":{"en":"A grain of history","tr":"Tarihten bir tutam","fa":"ذره‌ای از تاریخ"},"timed":20,"ctx":["RA-history"],"intro":"You should spend about 20 minutes on Questions 27-40, which are based on Reading Passage 3 below.","passage":"A grain of history\n\nFew substances have shaped human societies as profoundly as one that most of us now buy for a trivial sum and use without a second thought. Until the twentieth century, salt was a commodity of considerable value: it kept food edible through long winters and longer voyages, it provided governments with a dependable source of tax revenue, and it was carried by merchants across deserts and seas. Mark Kurlansky's Salt: A World History, first published in 2002, sets out to tell this story, from ancient China to the present day. It is an ambitious book, and in many ways a successful one, although it is not quite the history that its title promises.\n\nKurlansky is a journalist rather than an academic historian, and it shows, mostly in good ways. He writes clearly and with obvious enjoyment, and he has a gift for the revealing detail. Readers learn, for example, that in ancient China salt was obtained from underground brine, that workers drilled deep wells using bamboo, and that natural gas escaping from the same wells was eventually burned to boil the brine. Episodes like this, in which practical necessity drives ingenuity, are where the book is at its best: they show how the search for salt pushed people into technical inventions that they might otherwise never have made.\n\nThe book is organised partly by period and partly by place, moving from China to ancient Egypt and Rome, then to medieval Europe, and finally to the Americas and the modern world. Along the way, Kurlansky explains how salted fish, especially cod and herring, made long sea voyages possible, how Venice grew rich by controlling much of the salt trade, and how a hated tax on salt in France added to the anger that led to revolution. He also describes Gandhi's march to the sea in 1930, when thousands of Indians gathered salt in open defiance of the British tax on it.\n\nKurlansky draws on a remarkable range of sources, from ancient texts to the account books of merchants and descriptions of places where salt is still produced by traditional methods. This breadth is undeniably impressive, but it comes at a cost. At well over four hundred pages, the book asks a lot of its readers, and some of the more technical passages could have been shortened without any loss.\n\nThe more serious weakness lies in the way the book is put together: the chapters do not always add up to an argument. Kurlansky moves so rapidly from one illustration to the next that the reader is sometimes left wondering what, beyond the substance itself, connects them. A historian might reasonably ask why salt carried greater political weight in some societies than in others, or how fluctuations in its price affected the daily lives of ordinary people. Such questions are raised but rarely followed through, and the book is better described as a long series of stories than as a history with a clear thesis. Some reviewers have welcomed this, praising the book's energy. To me, it is a missed opportunity, because the material for a real argument is all there.\n\nKurlansky's habit of including recipes is a matter of taste. Many chapters contain old instructions for preparing salted foods, often quoted from historical cookbooks. Some readers will find these charming; others will skip them. I found that they made the past feel concrete, although a few are so long that they interrupt the narrative.\n\nOne of the most interesting themes, although it is never fully developed, is the way in which salt lost its importance. For most of history, salt was scarce enough to be worth fighting over. Then, in the nineteenth and twentieth centuries, advances in geology revealed huge underground deposits, while refrigeration and canning made salting far less necessary as a way of preserving food. Salt became cheap and ordinary. Kurlansky notes this change in his final chapters, but he spends far less time on it than on earlier periods, which is a pity, because it says a great deal about how a precious resource can suddenly lose its value.\n\nThere is also little here on salt and health, a subject that is hard to avoid today, when governments urge people to eat less of it. This omission is perhaps understandable in a work of history, but it means that readers learn little about how attitudes to salt, once regarded as essential to life, have been transformed in recent decades.\n\nDespite these reservations, Salt remains a rewarding book. It is entertaining, full of surprising information and written with real affection for its subject. Readers looking for a careful analysis of economic history should look elsewhere. Those who want to understand how an ordinary substance once shaped empires, trade routes and revolutions will find a great deal to enjoy.","groups":[{"instruction":"Questions 27-30. Choose the correct letter, A, B, C or D. Write the correct letter in boxes 27-30 on your answer sheet.","qtype":"mcq","questions":[{"n":27,"kind":"mcq","prompt":"What does the reviewer say about Kurlansky’s background as a journalist?","options":["A It explains why the book is enjoyable to read.","B It has led to some mistakes in the facts.","C It makes the book hard to follow.","D It is unusual for a writer on this subject."],"correct":0,"evidence":"He writes clearly and with obvious enjoyment","why":{"en":"\"It shows, mostly in good ways. He writes clearly and with obvious enjoyment.\" No mistakes are mentioned, and the structure problem is not linked to his background.","tr":"\"Belli oluyor, çoğunlukla iyi yönde. Açık ve belli bir keyifle yazıyor.\" Hata söz konusu değil; yapı sorunu da geçmişiyle ilişkilendirilmiyor.","fa":"«معلوم است، بیشتر به شکل خوب. روشن و با لذتی آشکار می‌نویسد». از اشتباه حرفی نیست و مشکل ساختار هم به پیشینه‌اش ربط داده نمی‌شود."},"trap":["TR-samewords","TR-paraphrase"]},{"n":28,"kind":"mcq","prompt":"The reviewer mentions salt production in ancient China in order to show","options":["A how salt was first discovered.","B that the need for salt encouraged new technology.","C that China produced more salt than other countries.","D how salt first reached Europe."],"correct":1,"evidence":"pushed people into technical inventions","why":{"en":"Drilling with bamboo and burning natural gas show how \"the search for salt pushed people into technical inventions\".","tr":"Bambuyla sondaj ve doğal gaz yakmak, \"tuz arayışının insanları teknik icatlara ittiğini\" gösteriyor.","fa":"حفاری با بامبو و سوزاندن گاز طبیعی نشان می‌دهند «جستجوی نمک مردم را به اختراع‌های فنی کشاند»."},"trap":["TR-paraphrase"]},{"n":29,"kind":"mcq","prompt":"What is the reviewer’s main criticism of the book?","options":["A It is too short to cover the subject.","B It is written in an academic style.","C It does not develop a clear argument.","D It leaves out the history of the Americas."],"correct":2,"evidence":"the chapters do not always add up to an argument","why":{"en":"The \"more serious weakness\": the chapters \"do not always add up to an argument\". The book is long, not academic, and it covers the Americas.","tr":"\"Daha ciddi zayıflık\": bölümler \"her zaman bir savda birleşmiyor\". Kitap uzun, akademik değil ve Amerika kıtasını da anlatıyor.","fa":"«ضعف جدی‌تر»: فصل‌ها «همیشه به یک استدلال نمی‌رسند». کتاب بلند است، دانشگاهی نیست و قاره‌ی آمریکا را هم پوشش می‌دهد."},"trap":["TR-samewords"]},{"n":30,"kind":"mcq","prompt":"What is the reviewer’s opinion of the recipes in the book?","options":["A They are the best part of the book.","B They help readers imagine life in the past.","C They should all have been left out.","D They are taken from modern cookbooks."],"correct":1,"evidence":"they made the past feel concrete","why":{"en":"\"I found that they made the past feel concrete\", even though a few are too long. They come from historical cookbooks.","tr":"\"Geçmişi somut hissettirdiklerini düşündüm\", birkaçı fazla uzun olsa da. Tarihî yemek kitaplarından alınmışlar.","fa":"«به نظرم گذشته را ملموس می‌کردند»، هرچند چندتایشان خیلی طولانی‌اند. از کتاب‌های آشپزی تاریخی آمده‌اند."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 31-36. Complete the summary using the list of words, A-I, below. Write the correct letter, A-I, in boxes 31-36 on your answer sheet.","qtype":"summary-box","summaryTitle":"How salt lost its value","bank":["A attention","B cheap","C deposits","D health","E preserve","F recipes","G refrigeration","H scarce","I trade"],"questions":[{"n":31,"kind":"match","prompt":"For most of history, salt was so ___ that people were willing to fight over it.","correct":7,"evidence":"salt was scarce enough to be worth fighting over","why":{"en":"\"Scarce enough to be worth fighting over\". Cheap (B) is the opposite of what the text says about that period.","tr":"\"Uğruna savaşılacak kadar kıt\". Ucuz (B) o dönem için metnin söylediğinin tersi.","fa":"«آن‌قدر کمیاب که ارزش جنگیدن داشت». ارزان (B) برعکس چیزی است که متن درباره‌ی آن دوره می‌گوید."},"trap":["TR-paraphrase"]},{"n":32,"kind":"match","prompt":"In the nineteenth and twentieth centuries, geologists found enormous underground ___,","correct":2,"evidence":"revealed huge underground deposits","why":{"en":"\"Advances in geology revealed huge underground deposits\": found = revealed.","tr":"\"Jeolojideki ilerlemeler yeraltında büyük yatakları ortaya çıkardı\": found = revealed.","fa":"«پیشرفت زمین‌شناسی ذخایر عظیم زیرزمینی را آشکار کرد»: found یعنی revealed."},"trap":["TR-paraphrase"]},{"n":33,"kind":"match","prompt":"while ___ and canning reduced the need for salting.","correct":6,"evidence":"refrigeration and canning made salting far less necessary","why":{"en":"\"Refrigeration and canning made salting far less necessary.\"","tr":"\"Soğutma ve konserve, tuzlamayı çok daha az gerekli hâle getirdi.\"","fa":"«یخچال و کنسروسازی نمک‌سود کردن را خیلی کمتر لازم کردند»."},"trap":["TR-paraphrase"]},{"n":34,"kind":"match","prompt":"Salt was no longer the main way to ___ food,","correct":4,"evidence":"as a way of preserving food","why":{"en":"\"As a way of preserving food\". The verb form in the box, preserve, fits \"to ___\".","tr":"\"Yiyeceği korumanın bir yolu olarak\". Kutudaki fiil biçimi preserve, \"to ___\" yapısına uyuyor.","fa":"«به‌عنوان راهی برای نگه‌داشتن غذا». شکل فعلی کادر، preserve، با «to ___» جور است."},"trap":["TR-paraphrase"]},{"n":35,"kind":"match","prompt":"and so it became ___ and ordinary.","correct":1,"evidence":"Salt became cheap and ordinary","why":{"en":"\"Salt became cheap and ordinary.\" Scarce (H) describes the earlier period.","tr":"\"Tuz ucuz ve sıradan oldu.\" Kıt (H) önceki dönemi anlatıyor.","fa":"«نمک ارزان و معمولی شد». کمیاب (H) دوره‌ی قبل را توصیف می‌کند."},"trap":["TR-samewords"]},{"n":36,"kind":"match","prompt":"The reviewer believes that Kurlansky gives this change too little ___.","correct":0,"evidence":"he spends far less time on it than on earlier periods","why":{"en":"\"He spends far less time on it\" = he gives it too little attention.","tr":"\"Ona çok daha az zaman ayırıyor\" = ona çok az ilgi gösteriyor.","fa":"«وقت خیلی کمتری رویش می‌گذارد» یعنی توجه کمی به آن می‌کند."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 37-40. Do the following statements agree with the views of the writer in Reading Passage 3? In boxes 37-40 on your answer sheet, write YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.","qtype":"ynng","questions":[{"n":37,"kind":"ynng","prompt":"Kurlansky’s background as a journalist is a weakness of the book.","correct":"NO","evidence":"and it shows, mostly in good ways","why":{"en":"\"It shows, mostly in good ways\": the writer sees it mainly as a strength.","tr":"\"Belli oluyor, çoğunlukla iyi yönde\": yazar bunu çoğunlukla bir güç olarak görüyor.","fa":"«معلوم است، بیشتر به شکل خوب»: نویسنده آن را بیشتر نقطه‌ی قوت می‌بیند."},"trap":["TR-whosevoice"]},{"n":38,"kind":"ynng","prompt":"The book would have been better with a clear central argument.","correct":"YES","evidence":"To me, it is a missed opportunity","why":{"en":"Other reviewers welcome the series of stories; the writer says: \"To me, it is a missed opportunity, because the material for a real argument is all there.\"","tr":"Başka eleştirmenler hikâyeler dizisini memnuniyetle karşılıyor; yazar diyor ki: \"Bana göre bu kaçırılmış bir fırsat, çünkü gerçek bir sav için malzemenin hepsi orada.\"","fa":"منتقدان دیگر از این مجموعه‌ی داستان‌ها استقبال می‌کنند؛ نویسنده می‌گوید: «به نظر من فرصتی ازدست‌رفته است، چون همه‌ی مواد یک استدلال واقعی آن‌جاست»."},"trap":["TR-whosevoice","TR-NGvsF"]},{"n":39,"kind":"ynng","prompt":"Kurlansky tested the recipes himself before including them.","correct":"NOT GIVEN","evidence":"often quoted from historical cookbooks","why":{"en":"The recipes are quoted from historical cookbooks; the review says nothing about testing them.","tr":"Tarifler tarihî yemek kitaplarından alıntı; eleştiri onları denemek hakkında bir şey söylemiyor.","fa":"دستورها از کتاب‌های آشپزی تاریخی نقل شده‌اند؛ نقد درباره‌ی امتحان کردنشان چیزی نمی‌گوید."},"trap":["TR-NGvsF"]},{"n":40,"kind":"ynng","prompt":"Readers who want a detailed study of economic history will be satisfied with the book.","correct":"NO","evidence":"should look elsewhere","why":{"en":"\"Readers looking for a careful analysis of economic history should look elsewhere.\"","tr":"\"Ekonomi tarihinin dikkatli bir analizini arayan okurlar başka yere bakmalı.\"","fa":"«خواننده‌هایی که دنبال تحلیل دقیق تاریخ اقتصادی‌اند باید جای دیگری را بگردند»."},"trap":["TR-whosevoice","TR-paraphrase"]}]}],"id":"c-x01-r3-d","course":"ielts-exams","exam":"exam-01","unit":"x01-r3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Salt was scarce for most of history.\" Scarce means...","options":["hard to find, not enough of it","dangerous to eat","very cheap"],"correct":0,"why":{"en":"Scarce = in short supply.","tr":"Scarce = kıt, az bulunan.","fa":"scarce یعنی کمیاب."}},{"tests":"paraphrase","point":2,"prompt":"In a summary, \"geologists found large deposits\". Which words in a text could mean the same?","options":["geologists were looking for","deposits were used up","advances in geology revealed"],"correct":2,"why":{"en":"\"Revealed\" = found or showed; \"advances in geology\" = geologists’ work.","tr":"\"Revealed\" = buldu ya da gösterdi; \"jeolojideki ilerlemeler\" = jeologların çalışması.","fa":"«revealed» یعنی پیدا کرد یا نشان داد؛ «پیشرفت زمین‌شناسی» یعنی کار زمین‌شناس‌ها."}},{"tests":"method","point":2,"prompt":"Summary gap: \"and so it became ___ and ordinary.\" Before choosing from the box, decide...","options":["that the gap needs a noun","that the gap needs an adjective","that the gap needs a verb"],"correct":1,"why":{"en":"\"Became ___ and ordinary\": ordinary is an adjective, so the gap is an adjective too.","tr":"\"Became ___ and ordinary\": ordinary bir sıfat, yani boşluk da sıfat.","fa":"«became ___ and ordinary»: ordinary صفت است، پس جای خالی هم صفت است."}},{"tests":"trap","point":3,"prompt":"Text: \"Several critics praised the novel’s ending. I was less convinced.\" Statement: \"The ending of the novel is excellent.\" YES, NO or NOT GIVEN (views of the writer)?","options":["NO","YES","NOT GIVEN"],"correct":0,"why":{"en":"The critics praise it; the writer was \"less convinced\", which goes against \"excellent\".","tr":"Eleştirmenler övüyor; yazar \"daha az ikna oldu\" ve bu \"mükemmel\" ile çelişiyor.","fa":"منتقدان تحسینش می‌کنند؛ نویسنده «کمتر قانع شد» که با «عالی» تناقض دارد."}}],"id":"c-x01-r3-x","course":"ielts-exams","exam":"exam-01","unit":"x01-r3"},"gt":{"explain":{"title":{"en":"GT Reading Section 3: a longer article","tr":"GT Reading Section 3: daha uzun bir makale","fa":"GT Reading Section 3: یک مقاله‌ی بلندتر"},"objective":{"en":"In this lesson you will learn to read a longer general article: complete notes with up to three words from the text, and decide TRUE, FALSE or NOT GIVEN when the text is careful about what is proved.","tr":"Bu derste daha uzun, genel bir makaleyi okumayı öğreneceksin: notları metinden en fazla üç kelimeyle tamamlayacak ve metin neyin kanıtlandığı konusunda temkinli olduğunda TRUE, FALSE ya da NOT GIVEN’a karar vereceksin.","fa":"در این درس یاد می‌گیری یک مقاله‌ی عمومیِ بلندتر را بخوانی: یادداشت‌ها را با حداکثر سه کلمه از متن کامل کنی و وقتی متن درباره‌ی چیزهای ثابت‌شده محتاط است، بین TRUE، FALSE و NOT GIVEN تصمیم بگیری."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"~800"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"3 words","tr":"3 kelime","fa":"۳ کلمه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: outdoor swimming","tr":"Bu sınav: açık havada yüzme","fa":"این آزمون: شنا در فضای باز"},"intro":{"en":"Section 3 is one long article for the general reader, about nature, history or modern life. It is the hardest GT text, and it often reports research carefully: some studies suggest, it has not been proved.","tr":"Section 3 genel okur için doğa, tarih ya da modern yaşam hakkında uzun tek bir makaledir. En zor GT metnidir ve araştırmaları çoğu zaman temkinle aktarır: \"some studies suggest\", \"it has not been proved\".","fa":"Section 3 یک مقاله‌ی بلند برای خواننده‌ی عام است، درباره‌ی طبیعت، تاریخ یا زندگی امروز. سخت‌ترین متن GT است و اغلب پژوهش‌ها را با احتیاط گزارش می‌کند: «some studies suggest»، «it has not been proved»."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x01-r3gt-ctx","exam":true,"patterns":["GT3-life"],"often":{"pattern":"GT3-life","n":14,"of":40,"label":{"en":"Comes up often in the real exam: 14 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 14’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۴ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"An article about a popular pastime","tr":"Popüler bir uğraş hakkında bir makale","fa":"مقاله‌ای درباره‌ی یک سرگرمی پرطرفدار"},"asks":{"en":"Section 3 is one longer article for a general reader: here about outdoor swimming, its history, its benefits, its risks and how people stay safe.","tr":"Section 3 genel okur için daha uzun tek bir makaledir: burada açık havada yüzme, tarihi, faydaları, riskleri ve insanların nasıl güvende kaldığı.","fa":"Section 3 یک مقاله‌ی بلندتر برای خواننده‌ی عام است: این‌جا درباره‌ی شنا در فضای باز، تاریخش، فایده‌ها، خطرها و اینکه آدم‌ها چطور ایمن می‌مانند."},"fields":["History","Who does it today","Benefits","Risks","Safety advice","Water quality"],"words":[{"a":"without help","b":"without any help from floats or boats","tr":"yardımsız","fa":"بدون کمک"},{"a":"most","b":"the great majority","tr":"çoğu","fa":"بیشترِ"},{"a":"for fun","b":"for enjoyment / to relax","tr":"eğlence için","fa":"برای تفریح"},{"a":"not proved","b":"there is no firm evidence","tr":"kanıtlanmadı","fa":"ثابت نشده"},{"a":"small studies","b":"research with few participants","tr":"küçük çalışmalar","fa":"پژوهش‌های کوچک"},{"a":"strongest at first","b":"worst at the start","tr":"ilk anda en güçlü","fa":"اول از همه شدیدتر"},{"a":"optional","b":"up to you","tr":"isteğe bağlı","fa":"اختیاری"},{"a":"must be worn","b":"are required","tr":"giyilmesi zorunlu","fa":"باید پوشیده شود"},{"a":"closed","b":"shut for a time","tr":"kapatıldı","fa":"بسته شد"},{"a":"polluted","b":"poor water quality","tr":"kirli","fa":"آلوده"}],"traps":[{"en":"\"A few small studies suggest that coffee helps memory, but this has not been proved.\" A statement that says \"it has been proved\" is FALSE. If the text stops after \"helps memory\", the same statement is NOT GIVEN.","tr":"\"Birkaç küçük çalışma kahvenin belleğe yardım ettiğini düşündürüyor, ama bu kanıtlanmadı.\" \"Kanıtlandı\" diyen bir ifade FALSE’tur. Metin \"belleğe yardım ettiğini\"de bitseydi, aynı ifade NOT GIVEN olurdu.","fa":"«چند پژوهش کوچک نشان می‌دهند قهوه شاید به حافظه کمک کند، اما این ثابت نشده». جمله‌ای که بگوید «ثابت شده» FALSE است. اگر متن بعد از «به حافظه کمک کند» تمام شود، همان جمله NOT GIVEN است."},{"en":"\"Helmets are required for children\" in the text and \"Everyone must wear a helmet\" in the statement: one word of quantity makes it FALSE.","tr":"Metinde \"çocuklar için kask zorunlu\", ifadede \"herkes kask takmalı\": tek bir miktar kelimesi onu FALSE yapar.","fa":"در متن «کلاه ایمنی برای بچه‌ها الزامی است» و در جمله «همه باید کلاه ایمنی بگذارند»: یک کلمه‌ی کمیت آن را FALSE می‌کند."}],"example":{"text":"\"Surveys show that the great majority of cyclists in the city ride for exercise rather than to get to work.\"","item":"Statement: Most cyclists in the city ride mainly to keep fit.","answer":"TRUE","why":{"en":"\"The great majority\" = most; \"for exercise\" = to keep fit.","tr":"\"Büyük çoğunluk\" = çoğu; \"egzersiz için\" = formda kalmak için.","fa":"«اکثریت بزرگ» یعنی بیشتر؛ «برای ورزش» یعنی برای سرحال ماندن."}}},{"id":"GT3-life","ctx":["GT3-life"],"title":{"en":"Society, work and daily life","tr":"Toplum, iş ve gündelik yaşam","fa":"جامعه، کار و زندگی روزمره"},"asks":{"en":"A text about modern life, work or society: a nursery without toys, emojis, a health programme, lessons in leadership, life in a cold town. Headings and multiple choice test the writer’s main points.","tr":"Modern yaşam, iş ya da toplum hakkında bir metin: oyuncaksız bir kreş, emojiler, bir sağlık programı, liderlik dersleri, soğuk bir kasabada yaşam. Başlıklar ve çoktan seçmeli sorular yazarın ana noktalarını sınar.","fa":"متنی درباره‌ی زندگی امروز، کار یا جامعه: مهدکودکی بدون اسباب‌بازی، ایموجی‌ها، یک برنامه‌ی سلامت، درس‌هایی درباره‌ی رهبری، زندگی در یک شهر سرد. عنوان‌ها و سؤال‌های چندگزینه‌ای نکته‌های اصلی نویسنده را می‌سنجند."},"fields":["An experiment that surprised parents","Mixed reactions from staff","The original purpose","Plans to expand the scheme","Which paragraph describes the results after a year?"],"words":[{"a":"scheme","b":"programme / project","tr":"program, uygulama","fa":"طرح"},{"a":"reaction","b":"response / what people thought","tr":"tepki","fa":"واکنش"},{"a":"mixed","b":"some liked it, others did not","tr":"karışık","fa":"دوگانه"},{"a":"surprising","b":"unexpected / few predicted it","tr":"şaşırtıcı","fa":"غافلگیرکننده"},{"a":"purpose","b":"aim / designed to","tr":"amaç","fa":"هدف"},{"a":"expand","b":"grow / extend to more places","tr":"genişletmek","fa":"گسترش دادن"},{"a":"residents","b":"locals / people who live there","tr":"sakinler","fa":"ساکنان"},{"a":"wellbeing","b":"health and happiness","tr":"iyi oluş","fa":"سلامت و رضایت"},{"a":"communicate","b":"express / get a message across","tr":"iletişim kurmak","fa":"ارتباط برقرار کردن"},{"a":"encourage","b":"motivate / persuade","tr":"teşvik etmek","fa":"تشویق کردن"},{"a":"trend","b":"something becoming common","tr":"eğilim","fa":"روند"},{"a":"outcome","b":"result / what happened","tr":"sonuç","fa":"نتیجه"}],"traps":[{"en":"\"Mixed reactions\" needs both sides in the paragraph. One positive comment is not enough.","tr":"\"Karışık tepkiler\" için paragrafta iki taraf da olmalı. Tek bir olumlu yorum yetmez.","fa":"«واکنش‌های دوگانه» یعنی هر دو طرف در پاراگراف باشند. یک نظر مثبت کافی نیست."},{"en":"The purpose of a scheme and its result are often in different paragraphs.","tr":"Bir uygulamanın amacı ve sonucu çoğu zaman farklı paragraflardadır.","fa":"هدف یک طرح و نتیجه‌اش اغلب در پاراگراف‌های جدا هستند."}],"example":{"text":"E  Not everyone was convinced. Several parents worried that their children would be bored without toys, while a few teachers felt the experiment had started too quickly. Others, however, praised the calmer atmosphere.","item":"Choose the heading for paragraph E:  i  Mixed reactions   ii  Children become bored   iii  How the toys were chosen","answer":"i","why":{"en":"Worries from parents and teachers, then praise from others: both sides, so mixed reactions.","tr":"Ebeveyn ve öğretmenlerin endişeleri, ardından başkalarının övgüsü: iki taraf da var, yani karışık tepkiler.","fa":"نگرانی پدر و مادرها و معلم‌ها، بعد تعریف دیگران: هر دو طرف هست، پس واکنش‌های دوگانه."}},"track":"gt","general":true,"patterns":["GT3-life"],"often":{"pattern":"GT3-life","n":14,"of":40,"label":{"en":"Comes up often in the real exam: 14 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 14’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۴ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Notes, then eight statements","tr":"Notlar, sonra sekiz ifade","fa":"یادداشت‌ها، بعد هشت جمله"},"body":{"en":"Questions 28-32: complete notes with NO MORE THAN THREE WORDS from the text. Questions 33-40: TRUE, FALSE or NOT GIVEN. Both follow the order of the article.","tr":"Soru 28-32: notları metinden EN FAZLA ÜÇ KELİMEYLE tamamla. Soru 33-40: TRUE, FALSE ya da NOT GIVEN. İkisi de makalenin sırasını izler.","fa":"سؤال‌های ۲۸ تا ۳۲: یادداشت‌ها را با حداکثر سه کلمه از متن کامل کن. سؤال‌های ۳۳ تا ۴۰: TRUE، FALSE یا NOT GIVEN. هر دو به ترتیب مقاله جلو می‌روند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Skim the article in two minutes: one idea per paragraph.","tr":"Makaleye iki dakikada göz gezdir: her paragrafta bir fikir.","fa":"در دو دقیقه مقاله را سریع نگاه کن: هر پاراگراف یک ایده."},{"en":"Use names, dates and numbers in the notes to find the right paragraph.","tr":"Doğru paragrafı bulmak için notlardaki isimleri, tarihleri ve sayıları kullan.","fa":"برای پیدا کردن پاراگراف درست از اسم‌ها، تاریخ‌ها و عددهای یادداشت استفاده کن."},{"en":"Copy up to three words; leave out words already printed in the note.","tr":"En fazla üç kelime kopyala; notta zaten yazılı olan kelimeleri ekleme.","fa":"حداکثر سه کلمه کپی کن؛ کلمه‌هایی را که در یادداشت چاپ شده‌اند ننویس."},{"en":"For each statement, compare its strength with the text: some or all, suggest or prove.","tr":"Her ifadenin gücünü metinle karşılaştır: bazı mı hepsi mi, düşündürüyor mu kanıtlıyor mu.","fa":"قدرت هر جمله را با متن مقایسه کن: بعضی یا همه، نشان می‌دهد یا ثابت می‌کند."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Careful words in the text","tr":"Metindeki temkinli kelimeler","fa":"کلمه‌های محتاطانه در متن"},"table":{"headers":{"en":["The text says","A statement that says","The answer"],"tr":["Metin diyor ki","İfade diyor ki","Cevap"],"fa":["متن می‌گوید","جمله می‌گوید","جواب"]},"rows":[["it has not been proved that...","it has been proved","FALSE"],["at some events","at all events","FALSE"],["many people say they feel calmer","doctors recommend it","NOT GIVEN"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One note, step by step","tr":"Bir not, adım adım","fa":"یک یادداشت، قدم به قدم"},"instruction":"Complete the notes below. Choose NO MORE THAN THREE WORDS from the text for each answer.","text":"\"The first public baths in the town were opened in 1846, next to the old fish market.\"","item":"1846 · first public baths built beside the ___","answer":"old fish market","walk":[{"en":"Find the date 1846 in the text.","tr":"Metinde 1846 tarihini bul.","fa":"تاریخ ۱۸۴۶ را در متن پیدا کن."},{"en":"\"Next to\" = beside.","tr":"\"Next to\" = beside.","fa":"«next to» یعنی beside."},{"en":"Copy three words: old fish market. \"the\" is printed.","tr":"Üç kelime kopyala: old fish market. \"the\" yazılı.","fa":"سه کلمه کپی کن: old fish market. «the» چاپ شده."}]},"quick":{"prompt":"Text: \"Some doctors believe that walking after meals may help digestion, but this has never been tested in a proper study.\" Statement: \"Studies have shown that walking after meals helps digestion.\"","options":["TRUE","NOT GIVEN","FALSE"],"correct":2,"why":{"en":"The text says it \"has never been tested\", so \"studies have shown\" contradicts it: FALSE. Without that last part, the answer would be NOT GIVEN.","tr":"Metin \"hiç test edilmedi\" diyor; yani \"çalışmalar gösterdi\" onunla çelişiyor: FALSE. O son kısım olmasaydı cevap NOT GIVEN olurdu.","fa":"متن می‌گوید «هیچ‌وقت آزمایش نشده»، پس «پژوهش‌ها نشان داده‌اند» با آن تناقض دارد: FALSE. اگر آن بخش آخر نبود، جواب NOT GIVEN می‌شد."}},"remember":{"en":"Notes: three words at most. Statements: check how sure the text is.","tr":"Notlar: en fazla üç kelime. İfadeler: metnin ne kadar emin olduğuna bak.","fa":"یادداشت‌ها: حداکثر سه کلمه. جمله‌ها: ببین متن چقدر مطمئن است."},"type":"explain","id":"c-x01-r3-e-gt","course":"ielts-exams","exam":"exam-01","unit":"x01-r3"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 3","title":{"en":"Into the open water","tr":"Açık sulara","fa":"به دل آب‌های باز"},"timed":20,"ctx":["GT3-life"],"texts":[{"title":"Into the open water","kind":"article","body":"On a cold morning in early spring, a small group gathers at the edge of a lake. Most are wearing nothing warmer than a swimming costume and a brightly coloured hat. They walk slowly into the water, gasp, laugh, and swim out towards a yellow buoy a hundred metres away. Twenty minutes later they are back on the shore, red-faced and cheerful, drinking hot tea from flasks. Scenes like this have become common in many countries in recent years, as more and more people choose to swim in lakes, rivers and the sea rather than in heated indoor pools.\n\nSwimming outdoors is, of course, nothing new. For most of history it was the only kind of swimming there was. In 1875 a merchant navy captain called Matthew Webb became the first person to swim the English Channel without any help from floats or boats, a crossing that took him nearly twenty-two hours. In the 1930s, many towns built outdoor pools known as lidos, and summer swimming became a popular form of leisure. Later in the twentieth century, however, many of these lidos closed, partly because they were expensive to repair and partly because heated indoor pools seemed more modern and comfortable. Swimming moved indoors, and for several decades swimming in lakes and rivers was seen as something only a few enthusiasts did.\n\nThe return to open water began among competitive swimmers. Long-distance races in lakes and the sea attracted growing numbers of entrants, and in 2008 a 10-kilometre open-water race was added to the Olympic Games. Yet today's swimmers are, for the most part, not racing at all. Clubs report that the great majority of their members swim for pleasure, for company or simply to be outdoors, and many never take part in a competition.\n\nAsk open-water swimmers why they do it and most will mention how they feel afterwards. Many describe a sense of calm that lasts for hours. Some say that regular cold-water swimming has helped them through periods of stress or low mood. Scientists are interested in these claims, and several small studies have reported benefits for mood and sleep. However, researchers point out that the studies have involved only a small number of people, and that swimmers who feel better may also be enjoying fresh air, exercise and friendship. It has certainly not been proved that cold water itself prevents illness.\n\nWhat is clear is that open water carries risks that indoor pools do not. The most serious is cold water shock. When the body enters cold water, breathing becomes fast and uncontrolled, and the swimmer may take a sudden deep breath, sometimes while their head is under the water. This reaction is strongest in the first minute, which is why experienced swimmers always enter the water slowly and wait for their breathing to settle before they start to swim.\n\nOther advice is simple. Swimmers should never swim alone, and they should agree on a route before they set off. A brightly coloured hat makes them easier to see, and many now also take a tow float, a small inflatable bag that is tied around the waist and floats behind them. If they get tired, they can hold on to it and rest, and some tow floats even have a dry pocket for a phone or keys. Swimmers who are new to the sport are advised to join a group or a club, where more experienced members can show them safe places to get in and out. It is also important to know where to get out of the water, because steep or muddy banks can be difficult to climb.\n\nWetsuits are a matter of choice for most swimmers. Many people wear them in spring and autumn for warmth, while others prefer the feeling of swimming without one. At some organised events, however, wetsuits must be worn when the water is below a certain temperature.\n\nWater quality is another concern. After heavy rain, rivers and beaches can become polluted, and in some places popular swimming spots have been closed for several days at a time until tests show that the water is safe again. Many swimmers now check water-quality information online before they go, and some groups have started testing the water themselves and sharing the results with their local council.\n\nFor all these warnings, the number of people swimming outdoors continues to grow. Local councils have reopened old lidos, and new swimming groups appear every year. For many of their members, the attraction is simple: an hour in cold water, followed by a hot drink with friends, is one of the best ways they know to start the day."}],"groups":[{"text":0,"instruction":"Questions 28-32. Complete the notes below. Choose NO MORE THAN THREE WORDS from the text for each answer.","qtype":"note","notesTitle":"Open-water swimming","questions":[{"n":28,"kind":"gap","prompt":"1875 · first person to swim the English Channel without help: ___","accept":["Matthew Webb","Webb"],"limit":3,"evidence":"a merchant navy captain called Matthew Webb","why":{"en":"\"A merchant navy captain called Matthew Webb\". Two words, spelled as in the text.","tr":"\"Matthew Webb adında bir ticaret gemisi kaptanı\". Metindeki gibi yazılmış iki kelime.","fa":"«ناخدای کشتی تجاری به نام Matthew Webb». دو کلمه، با همان املای متن."},"trap":["TR-limit"]},{"n":29,"kind":"gap","prompt":"1930s · many towns built outdoor pools called ___","accept":["lidos"],"limit":3,"evidence":"outdoor pools known as lidos","why":{"en":"\"Outdoor pools known as lidos\": called = known as.","tr":"\"Lido olarak bilinen açık havuzlar\": called = known as.","fa":"«استخرهای روباز معروف به lido»: called یعنی known as."},"trap":["TR-paraphrase"]},{"n":30,"kind":"gap","prompt":"2008 · a 10-kilometre race added to the ___","accept":["Olympic Games","Olympics"],"limit":3,"evidence":"added to the Olympic Games","why":{"en":"\"Added to the Olympic Games.\" \"the\" is printed.","tr":"\"Olimpiyat Oyunları’na eklendi.\" \"the\" yazılı.","fa":"«به بازی‌های المپیک اضافه شد». «the» چاپ شده."},"trap":["TR-limit"]},{"n":31,"kind":"gap","prompt":"Main risk · ___, strongest in the first minute","accept":["cold water shock"],"limit":3,"evidence":"The most serious is cold water shock","why":{"en":"\"The most serious is cold water shock\": main risk = most serious. Three words exactly.","tr":"\"En ciddisi soğuk su şoku\": main risk = most serious. Tam üç kelime.","fa":"«جدی‌ترینش شوک آب سرد است»: main risk یعنی most serious. دقیقاً سه کلمه."},"trap":["TR-limit","TR-paraphrase"]},{"n":32,"kind":"gap","prompt":"Safety · take a ___ that floats behind you and can be used for resting","accept":["tow float"],"limit":3,"evidence":"many now also take a tow float","why":{"en":"\"A tow float, a small inflatable bag... If they get tired, they can hold on to it and rest.\"","tr":"\"Bir tow float, küçük şişirilebilir bir çanta... Yorulurlarsa ona tutunup dinlenebilirler.\"","fa":"«یک tow float، کیسه‌ای کوچک و بادی... اگر خسته شوند می‌توانند آن را بگیرند و استراحت کنند»."},"trap":["TR-limit"]}]},{"text":0,"instruction":"Questions 33-40. Do the following statements agree with the information given in the text? Write TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.","qtype":"tfng","questions":[{"n":33,"kind":"tfng","prompt":"Open-water swimming is more popular in rivers than in the sea.","correct":"NOT GIVEN","evidence":"choose to swim in lakes, rivers and the sea","why":{"en":"Lakes, rivers and the sea are listed together; nothing compares them.","tr":"Göller, nehirler ve deniz birlikte sayılıyor; hiçbiri karşılaştırılmıyor.","fa":"دریاچه، رودخانه و دریا با هم فهرست شده‌اند؛ هیچ مقایسه‌ای نیست."},"trap":["TR-NGvsF"]},{"n":34,"kind":"tfng","prompt":"Matthew Webb’s crossing took less than a day.","correct":"TRUE","evidence":"a crossing that took him nearly twenty-two hours","why":{"en":"\"Nearly twenty-two hours\" is less than a day.","tr":"\"Yaklaşık yirmi iki saat\" bir günden az.","fa":"«نزدیک بیست‌ودو ساعت» کمتر از یک روز است."},"trap":["TR-paraphrase"]},{"n":35,"kind":"tfng","prompt":"Most members of open-water swimming clubs take part in races.","correct":"FALSE","evidence":"the great majority of their members swim for pleasure","why":{"en":"\"The great majority... swim for pleasure... and many never take part in a competition.\"","tr":"\"Büyük çoğunluğu... zevk için yüzüyor... ve birçoğu hiç yarışmaya katılmıyor.\"","fa":"«اکثریت بزرگ... برای لذت شنا می‌کنند... و خیلی‌ها هیچ‌وقت در مسابقه شرکت نمی‌کنند»."},"trap":["TR-NGvsF","TR-paraphrase"]},{"n":36,"kind":"tfng","prompt":"Research has proved that cold water helps to prevent illness.","correct":"FALSE","evidence":"It has certainly not been proved","why":{"en":"Small studies report benefits, but \"it has certainly not been proved that cold water itself prevents illness\".","tr":"Küçük çalışmalar fayda bildiriyor, ama \"soğuk suyun kendisinin hastalığı önlediği kesinlikle kanıtlanmadı\".","fa":"پژوهش‌های کوچک فایده‌هایی گزارش کرده‌اند، اما «قطعاً ثابت نشده که خودِ آب سرد از بیماری پیشگیری می‌کند»."},"trap":["TR-hedge","TR-NGvsF"]},{"n":37,"kind":"tfng","prompt":"The body’s reaction to cold water is strongest in the first minute.","correct":"TRUE","evidence":"This reaction is strongest in the first minute","why":{"en":"\"This reaction is strongest in the first minute.\"","tr":"\"Bu tepki ilk dakikada en güçlüdür.\"","fa":"«این واکنش در دقیقه‌ی اول از همه شدیدتر است»."},"trap":["TR-NGvsF"]},{"n":38,"kind":"tfng","prompt":"Swimmers who use a tow float stay warmer in the water.","correct":"NOT GIVEN","evidence":"many now also take a tow float","why":{"en":"The tow float helps swimmers to be seen and to rest; warmth is not mentioned.","tr":"Tow float yüzücülerin görülmesine ve dinlenmesine yardım ediyor; sıcaklıktan söz edilmiyor.","fa":"tow float کمک می‌کند شناگر دیده شود و استراحت کند؛ از گرما حرفی نیست."},"trap":["TR-NGvsF"]},{"n":39,"kind":"tfng","prompt":"Wetsuits must be worn at all organised swimming events.","correct":"FALSE","evidence":"At some organised events, however, wetsuits must be worn","why":{"en":"\"At some organised events\", and only below a certain temperature. \"All\" contradicts this.","tr":"\"Bazı organize etkinliklerde\" ve yalnızca belli bir sıcaklığın altında. \"All\" bununla çelişiyor.","fa":"«در بعضی رویدادهای سازمان‌یافته» و فقط زیر دمای مشخص. «all» با این تناقض دارد."},"trap":["TR-NGvsF","TR-hedge"]},{"n":40,"kind":"tfng","prompt":"Some swimming places have been closed for a time because of pollution.","correct":"TRUE","evidence":"popular swimming spots have been closed for several days","why":{"en":"After heavy rain, polluted spots \"have been closed for several days at a time\".","tr":"Şiddetli yağmurdan sonra kirlenen yerler \"bir seferde birkaç gün kapatıldı\".","fa":"بعد از باران شدید، جاهای آلوده «هر بار چند روز بسته شده‌اند»."},"trap":["TR-paraphrase"]}]}],"id":"c-x01-r3-d-gt","course":"ielts-exams","exam":"exam-01","unit":"x01-r3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Wetsuits are a matter of choice.\" This means wetsuits are...","options":["required","optional","not allowed"],"correct":1,"why":{"en":"A matter of choice = you decide = optional.","tr":"Bir tercih meselesi = sen karar verirsin = isteğe bağlı.","fa":"موضوعِ انتخاب یعنی خودت تصمیم می‌گیری، یعنی اختیاری."}},{"tests":"paraphrase","point":1,"prompt":"A statement says \"most members\". Which words in a text mean the same?","options":["the great majority of members","a few members","some members"],"correct":0,"why":{"en":"\"The great majority\" = most.","tr":"\"Büyük çoğunluk\" = çoğu.","fa":"«اکثریت بزرگ» یعنی بیشتر."}},{"tests":"method","point":2,"prompt":"Note: \"Main risk: ___\" (NO MORE THAN THREE WORDS). The text says \"the most serious is sudden cold water shock\". You write...","options":["sudden cold water shock","the most serious","cold water shock"],"correct":2,"why":{"en":"\"sudden cold water shock\" is four words. \"cold water shock\" names the risk in three.","tr":"\"sudden cold water shock\" dört kelime. \"cold water shock\" riski üç kelimeyle söylüyor.","fa":"«sudden cold water shock» چهار کلمه است. «cold water shock» خطر را با سه کلمه می‌گوید."}},{"tests":"trap","point":3,"prompt":"Text: \"Some swimmers say the cold helps them sleep.\" Statement: \"Doctors recommend cold water swimming for better sleep.\"","options":["TRUE","NOT GIVEN","FALSE"],"correct":1,"why":{"en":"The text reports what swimmers say; it says nothing about doctors.","tr":"Metin yüzücülerin ne dediğini aktarıyor; doktorlar hakkında bir şey söylemiyor.","fa":"متن حرف شناگرها را نقل می‌کند؛ درباره‌ی پزشک‌ها چیزی نمی‌گوید."}}],"id":"c-x01-r3-x-gt","course":"ielts-exams","exam":"exam-01","unit":"x01-r3"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
